namespace SonTinhThuyTinh.Audio
{
    // One-shot sounds. The clips behind them live in the AudioLibrary (Assets/Resources/AudioLibrary.asset), generated by
    // Tools > Son Tinh Thuy Tinh > Audio > Generate Placeholder Audio and replaceable by real recordings (docs/progress.md 9.25).
    public enum Sfx
    {
        None = 0,

        // interface and story
        UiClick, DialogueBlip, GiftCollected, Notice, QuestAccept, QuestDone,

        // the player
        FootstepGrass, FootstepStone, FootstepWet, Jump, Land, Dodge, Slide, Climb,
        SwingLight, SwingHeavy, Hurt, Death, Block,

        // Son Tinh's earth spells (U / I / O) and Thuy Tinh's water spells
        EarthSpell0, EarthSpell1, EarthSpell2, WaterSpell0, WaterSpell1, WaterSpell2,

        // enemies and the world
        HitFlesh, HitHeavy, EnemyDeath, BellRing, WoodCrash, HorseNeigh, RoosterCluck, Splash, Thunder,
        ElephantRoar, ElephantStomp, CrocodileRoar,

        // battle cries (voiced "hah!"): the heroes' heavy blow and their spells
        SonShoutHeavy, SonShoutSpell, ThuyShoutHeavy, ThuyShoutSpell,
    }

    // Who is talking in a dialogue line: each voice has its own pitch and vowels (AudioManager plays a babble of syllables while the
    // line is typed, the way many games voice their text without recorded speech). Picked from DialogueLine.speaker.
    public enum VoiceId
    {
        None = 0,
        SonTinh, ThuyTinh, KingHung, MiNuong, Elder, Thief, Elephant, Narrator,
    }

    // Looping sounds: one music track and one ambience bed per scene (AudioManager decides which).
    public enum LoopId
    {
        None = 0,
        MusicMenu, MusicSonTinh, MusicThuyTinh, MusicPalace, MusicCutscene, MusicBattle,
        AmbForest, AmbWater, AmbPalace, AmbWind,
    }
}
